@startuml

class Faculty {
  +name : string
}

class Institute {
  +name : string
  +address : string
}

class Employee {
  +socialSecurityNumber : string
  +name : string
  +emailAddress : string
}

class ResearchStaff extends Employee {}

class AdministrativeStaff extends Employee {}

class ResearchAssistant extends ResearchStaff {
  +fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class Project {
  +name : string
  +startDate : date
  +endDate : date
  +hours : int
}

class Course {
  +id : int
  +name : string
  +weeklyDuration : int
}

Faculty "1" -- "*" Institute
Faculty "1" -- "1" Employee : headed by (dean)
Institute "1" -- "*" ResearchAssistant : has
ResearchAssistant "1" -- "*" Project : involved in
ResearchAssistant "1" -- "*" Course : teaches

@enduml

